class S5i5(ARCBaseGame):
    """








    """



    step_counter: StepCounter
    socket_arms:  dict
    arm_children: dict
    saved_state:  dict
    last_pivot:   "Sprite | None"
    last_pivot_dir: int

    def __init__(self) -> None:
        """"""




        self._log_state = ActionLogState(aggregator=default_aggregator, post_process=compose_default_summary)
        self._frame_sprite_log:     list[list[dict]] = []
        self._frame_nonsprite_log:  list[list[dict]] = []

        self.step_counter = StepCounter(0)
        camera = GameCamera(
            background=BACKGROUND_COLOR,
            letter_box=PADDING_COLOR,
            interfaces=[self.step_counter],
        )
        super().__init__(game_id="s5i5", levels=levels, camera=camera, available_actions=[6])

    def _get_hidden_state(self) -> np.ndarray:
        """



        """
        state = np.zeros((1, 1), dtype=np.int16)
        state[0] = self.step_counter.current_steps
        return state

    def _get_valid_actions(self) -> list[ActionInput]:
        """






        """
        valid_actions: list[ActionInput] = []

        double_sockets = self.current_level.get_sprites_by_tag("double_socket")
        for socket in double_sockets:
            x = socket.x
            y = socket.y
            action = ActionInput(id=GameAction.ACTION6.value, data={"x": x, "y": y})
            valid_actions.append(action)

            if socket.width > socket.height:
                x = socket.x + 7
            else:
                y = socket.y + 7
            action = ActionInput(id=GameAction.ACTION6.value, data={"x": x, "y": y})
            valid_actions.append(action)

        pivots = self.current_level.get_sprites_by_tag("pivot")
        for pivot in pivots:
            x = pivot.x
            y = pivot.y
            action = ActionInput(id=GameAction.ACTION6.value, data={"x": x, "y": y})
            valid_actions.append(action)
        return valid_actions

    def on_set_level(self, level: Level) -> None:
        """






        """
        self._init_counter()
        self.last_pivot    = None
        self.last_pivot_dir = -1
        self.socket_arms  = dict()
        self.arm_children = dict()
        self.saved_state  = dict()



        self._target_dot_covered_state: dict[int, bool] = {}


        double_sockets = self.current_level.get_sprites_by_tag("double_socket")
        for socket in double_sockets:
            self.socket_arms[socket] = []

        arm_sprites  = self.current_level.get_sprites_by_tag("arm")
        hole_sprites = self.current_level.get_sprites_by_tag("target_hole")

        for arm in arm_sprites:

            arm_color = arm.pixels[1, 1]

            matching_sockets = [s for s in double_sockets if arm_color in s.pixels]
            for socket in matching_sockets:
                self.socket_arms[socket].append(arm)

            self.arm_children[arm] = set()
            for hole in hole_sprites:
                if hole.collides_with(arm):
                    self.arm_children[arm].add(hole)


        children_data = self.current_level.get_data("Children")
        if children_data:
            for parent_name, child_name in children_data:
                parents  = self.current_level.get_sprites_by_name(parent_name)
                children = self.current_level.get_sprites_by_name(child_name)
                for parent in parents:
                    for child in children:
                        self.arm_children[parent].add(child)








        self._arm_role_by_id = {}
        _socket_armed_ids = set()
        for _arms in self.socket_arms.values():
            for _a in _arms:
                _socket_armed_ids.add(id(_a))
        _chained_arm_ids = set()
        for _parent, _children in self.arm_children.items():
            for _c in _children:
                if "arm" in (_c.tags or []):
                    _chained_arm_ids.add(id(_c))
        for _arm in arm_sprites:
            _dx, _dy, _dw, _dh = self._to_display_bbox(_arm)

            if _arm.name in _FORCE_EXTENDING_ARM_NAMES:
                _role = "extending_arm"
            elif _dx + _dw <= 0 or _dy + _dh <= 0 or _dx >= 64 or _dy >= 64:
                _role = "anomaly_arm"
            elif id(_arm) in _socket_armed_ids:
                _role = "extending_arm"
            elif id(_arm) in _chained_arm_ids:
                _role = "chained_arm"
            else:
                _role = "fixed_arm"
            self._arm_role_by_id[id(_arm)] = _role



        for _spr in self.current_level.get_sprites():
            if _spr.name in _FORCE_EXTENDING_ARM_NAMES and id(_spr) not in self._arm_role_by_id:
                self._arm_role_by_id[id(_spr)] = "extending_arm"





        _LAYOUT_TARGET_ROLES = {
            "double_socket",
            "target_hole",
            "extending_arm",
            "target_dot",
            "chained_arm",
            "pivot",
        }
        _layout_rows: list[dict] = []
        for _spr in self.current_level.get_sprites():
            if not _spr.is_visible:
                continue
            _t, _le, _l2 = self._display_for(_spr)
            if _t not in _LAYOUT_TARGET_ROLES:
                continue
            _dx, _dy, _dw, _dh = self._to_display_bbox(_spr)
            _layout_rows.append({
                "role":    _t,
                "role_l2": _l2,
                "sname":   _spr.name,
                "dx":      _dx, "dy": _dy, "dw": _dw, "dh": _dh,
            })
        if _layout_rows:
            self._set_event("initial_layout", _layout_rows)

    def _arm_role(self, spr) -> tuple[str, str, str]:
        """
        """
        role = self._arm_role_by_id.get(id(spr))
        if role is None or role not in TAG_DISPLAY_NAMES:
            return (None, None, None)
        return (role, TAG_DISPLAY_NAMES[role], TAG_DISPLAY_NAMES_L2.get(role, TAG_DISPLAY_NAMES[role]))

    def _display_for(self, spr) -> tuple[str, str, str]:
        """






        """
        arm_t, arm_le, arm_lj = self._arm_role(spr)
        if arm_le is not None:
            return (arm_t, arm_le, arm_lj)
        tags = list(spr._tags) if spr._tags else []
        for t in tags:
            if t in TAG_DISPLAY_NAMES:
                return (t, TAG_DISPLAY_NAMES[t], TAG_DISPLAY_NAMES_L2.get(t, TAG_DISPLAY_NAMES[t]))
        return (spr.name, spr.name, spr.name)

    def _display_for_snap(self, spr_id: int, name: str, tags: list) -> tuple[str, str, str]:
        """


        """
        role = self._arm_role_by_id.get(spr_id)
        if role and role in TAG_DISPLAY_NAMES:
            return (role, TAG_DISPLAY_NAMES[role], TAG_DISPLAY_NAMES_L2.get(role, TAG_DISPLAY_NAMES[role]))
        if name in _FORCE_EXTENDING_ARM_NAMES:
            return ("extending_arm", TAG_DISPLAY_NAMES["extending_arm"], TAG_DISPLAY_NAMES_L2["extending_arm"])
        for t in (tags or []):
            if t in TAG_DISPLAY_NAMES:
                return (t, TAG_DISPLAY_NAMES[t], TAG_DISPLAY_NAMES_L2.get(t, TAG_DISPLAY_NAMES[t]))
        return (name, name, name)

    def _init_counter(self) -> None:
        """"""
        budget = self.current_level.get_data("StepCounter")
        self.step_counter.max_steps = budget
        self.step_counter.reset()

    def _check_win(self) -> bool:
        """



        """
        dots  = self.current_level.get_sprites_by_tag("target_dot")
        holes = self.current_level.get_sprites_by_tag("target_hole")
        for dot in dots:
            if not any(hole.x == dot.x and hole.y == dot.y for hole in holes):
                return False
        return True

    def _get_arm_tip_rect(self, arm: Sprite) -> tuple[int, int, int, int]:
        """









        """
        direction = self._get_arm_direction(arm)
        if direction == 0:

            return (arm.x, arm.y, ARM_WIDTH, ARM_WIDTH)
        elif direction == 90:

            return (arm.x + arm.width - ARM_WIDTH, arm.y, ARM_WIDTH, ARM_WIDTH)
        elif direction == 180:

            return (arm.x, arm.y + arm.height - ARM_WIDTH, ARM_WIDTH, ARM_WIDTH)
        else:

            return (arm.x, arm.y, ARM_WIDTH, ARM_WIDTH)

    def _rects_overlap(
        self,
        a: tuple[int, int, int, int],
        b: tuple[int, int, int, int],
    ) -> bool:
        """"""
        ax, ay, aw, ah = a
        bx, by, bw, bh = b
        return not (ax + aw <= bx or bx + bw <= ax or ay + ah <= by or by + bh <= ay)

    def _pixel_overlap(self, a: Sprite, b: Sprite) -> bool:
        """




        """
        ax0, ay0 = a.x, a.y
        ax1, ay1 = ax0 + a.width, ay0 + a.height
        bx0, by0 = b.x, b.y
        bx1, by1 = bx0 + b.width, by0 + b.height
        ox0 = max(ax0, bx0)
        oy0 = max(ay0, by0)
        ox1 = min(ax1, bx1)
        oy1 = min(ay1, by1)
        if ox0 >= ox1 or oy0 >= oy1:
            return False
        a_sub = a.pixels[oy0 - ay0 : oy1 - ay0, ox0 - ax0 : ox1 - ax0]
        b_sub = b.pixels[oy0 - by0 : oy1 - by0, ox0 - bx0 : ox1 - bx0]
        return bool(((a_sub >= 0) & (b_sub >= 0)).any())

    def _log_arm_dot_contacts(self) -> None:
        """







        """
        arms = self.current_level.get_sprites_by_tag("arm")
        dots = self.current_level.get_sprites_by_tag("target_dot")

        current_covered: dict[int, bool] = {id(d): False for d in dots}
        for dot in dots:
            for arm in arms:
                if self._pixel_overlap(arm, dot):
                    current_covered[id(dot)] = True
                    break


        for dot in dots:
            dot_id = id(dot)
            now_covered  = current_covered[dot_id]
            prev_covered = self._target_dot_covered_state.get(dot_id, False)
            if now_covered == prev_covered:
                continue
            dx, dy, dw, dh = self._to_display_bbox(dot)

            if now_covered:
                self.action_log.append(
                    f"[disappear]:[target_dot]:[sname(target_dot);position({dx}_{dy});bbox({dw}_{dh})]:"
                    f"Target Hole at ({dx},{dy}) is hidden under an Arm."
                    f"|Object at ({dx},{dy}) is hidden under an Object."
                )
                self.action_log_l2.append(
                    f"[disappear]:[target_dot]:[sname(target_dot);position({dx}_{dy});bbox({dw}_{dh})]:"
                    f"({dx},{dy})"
                    f"|Object({dx},{dy})Object"
                )
            else:
                self.action_log.append(
                    f"[appear]:[target_dot]:[sname(target_dot);position({dx}_{dy});bbox({dw}_{dh})]:"
                    f"Target Hole at ({dx},{dy}) is no longer covered and reappears."
                    f"|Object at ({dx},{dy}) is no longer covered and reappears."
                )
                self.action_log_l2.append(
                    f"[appear]:[target_dot]:[sname(target_dot);position({dx}_{dy});bbox({dw}_{dh})]:"
                    f"({dx},{dy})"
                    f"|Object({dx},{dy})"
                )


        self._target_dot_covered_state = current_covered

    def _get_socket_color(self, socket: Sprite) -> int:
        """













        """
        arm_colors = set(COLOR_NAMES_EN.keys()) - {13}
        for row in socket.pixels:
            for val in row:
                v = int(val)
                if v in arm_colors:
                    return v
        return -1

    def _move_with_children(self, sprite: Sprite, dx: int, dy: int) -> None:
        """





        """
        sprite.move(dx, dy)
        if sprite in self.arm_children:
            for child in self.arm_children[sprite]:
                self._move_with_children(child, dx, dy)

    def _save_state(self, sprite: Sprite) -> None:
        """



        """
        self.saved_state[sprite] = sprite.clone()
        if sprite in self.arm_children:
            for child in self.arm_children[sprite]:
                self._save_state(child)

    def _get_arm_direction(self, arm: Sprite) -> int:
        """












        """
        if arm.pixels[-1, 1] == GRAY_STRIPE:
            return 0
        elif arm.pixels[1, 0] == GRAY_STRIPE:
            return 90
        elif arm.pixels[0, 1] == GRAY_STRIPE:
            return 180
        else:
            return 270

    def _mark_follower_descendants(self, arm: Sprite) -> None:
        """


        """
        for child in self.arm_children.get(arm, ()):
            self._arms_following_resize_this_step.add(id(child))
            self._mark_follower_descendants(child)

    def _resize_arm(self, arm: Sprite, index: int) -> None:
        """








        """
        arm_color  = arm.pixels[1, 1]
        old_height, old_width = arm.pixels.shape
        new_length = index * ARM_WIDTH
        direction  = self._get_arm_direction(arm)
        dx = 0
        dy = 0

        if direction == 0:

            arm.pixels = np.full((new_length, ARM_WIDTH), arm_color)
            arm.pixels[-1, :] = GRAY_STRIPE
            dy = -(new_length - old_height)
            arm.move(0, dy)
        elif direction == 90:

            arm.pixels = np.full((ARM_WIDTH, new_length), arm_color)
            arm.pixels[:, 0] = GRAY_STRIPE
            dx = new_length - old_width
        elif direction == 180:

            arm.pixels = np.full((new_length, ARM_WIDTH), arm_color)
            arm.pixels[0, :] = GRAY_STRIPE
            dy = new_length - old_height
        else:

            arm.pixels = np.full((ARM_WIDTH, new_length), arm_color)
            arm.pixels[:, -1] = GRAY_STRIPE
            dx = -(new_length - old_width)
            arm.move(dx, 0)


        for child in self.arm_children[arm]:
            self._move_with_children(child, dx, dy)


        self._mark_follower_descendants(arm)

    def _check_arm_overlap(self) -> bool:
        """



        """
        arm_sprites = self.current_level.get_sprites_by_tag("arm")
        for arm in arm_sprites:
            if any(arm.collides_with(other) for other in arm_sprites):
                return True
        return False

    def _rotate_sprite(self, arm: Sprite, pivot_x: int, pivot_y: int) -> None:
        """









        """





        self._arms_rotated_as_follower_this_step.add(id(arm))
        self._arm_rotation_count_this_step[id(arm)] = (
            self._arm_rotation_count_this_step.get(id(arm), 0) + 1
        )
        dx = pivot_x - arm.x
        dy = pivot_y - arm.y
        arm.set_position(pivot_x - dy, pivot_y + dx - (arm.width - ARM_WIDTH))
        arm.pixels = np.rot90(arm.pixels)
        if arm in self.arm_children:
            for child in self.arm_children[arm]:
                self._rotate_sprite(child, pivot_x, pivot_y)

    def _rotate_arm_90(self, arm: Sprite) -> None:
        """






        """
        direction = self._get_arm_direction(arm)
        if direction == 0:

            pivot_x = arm.x
            pivot_y = arm.y + arm.height - ARM_WIDTH
            for child in self.arm_children[arm]:
                self._rotate_sprite(child, pivot_x, pivot_y)
            arm.move(-arm.height + ARM_WIDTH, arm.height - ARM_WIDTH)
        elif direction == 90:

            pivot_x = arm.x
            pivot_y = arm.y
            for child in self.arm_children[arm]:
                self._rotate_sprite(child, pivot_x, pivot_y)
            arm.move(0, -arm.width + ARM_WIDTH)
        elif direction == 180:

            pivot_x = arm.x
            pivot_y = arm.y
            for child in self.arm_children[arm]:
                self._rotate_sprite(child, pivot_x, pivot_y)

        elif direction == 270:

            pivot_x = arm.x + arm.width - ARM_WIDTH
            pivot_y = arm.y
            for child in self.arm_children[arm]:
                self._rotate_sprite(child, pivot_x, pivot_y)
            arm.move(arm.width - ARM_WIDTH, 0)
        arm.pixels = np.rot90(arm.pixels)

        self._arm_rotation_count_this_step[id(arm)] = (
            self._arm_rotation_count_this_step.get(id(arm), 0) + 1
        )

    def _to_display_xy(self, x: int, y: int) -> tuple[int, int]:
        """



        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        return (x - cam.x) * arc_scale + x_off, (y - cam.y) * arc_scale + y_off


    def _to_display_bbox(self, spr) -> tuple[int, int, int, int]:
        """

        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        dx = (spr.x - cam.x) * arc_scale + x_off
        dy = (spr.y - cam.y) * arc_scale + y_off
        dw = spr.width  * arc_scale
        dh = spr.height * arc_scale
        return dx, dy, dw, dh

    def _bar_pixel_len(self, value: int) -> int:
        """



        """
        max_steps = self.step_counter.max_steps
        if max_steps == 0:
            return 0
        ratio = value / max_steps
        return round(64 * ratio)

    def _post_step(self, before_sprites: dict, before_steps: int) -> None:
        """





        """
        after_sprites = {id(spr): spr for spr in self.current_level.get_sprites()}


        for spr_id, spr in after_sprites.items():
            b = before_sprites.get(spr_id)
            if b is None or (not b["visible"] and spr.is_visible):
                dx, dy, dw, dh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr)
                self.action_log.append(
                    f"[appear]:[{_t}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{_le} appears at ({dx},{dy}).|Object appears at ({dx},{dy})."
                )
                self.action_log_l2.append(
                    f"[appear]:[{_t}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{_l2}({dx},{dy})|Object({dx},{dy})"
                )



        _arc_scale_d = min(64 // self.camera.width, 64 // self.camera.height)
        for spr_id, b in before_sprites.items():
            spr = after_sprites.get(spr_id)
            gone = spr is None and b["visible"]
            hid  = spr is not None and b["visible"] and not spr.is_visible
            if gone or hid:
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                bdw = int(b.get("width", 0))  * _arc_scale_d
                bdh = int(b.get("height", 0)) * _arc_scale_d
                _t, _le, _l2 = self._display_for_snap(spr_id, b['name'], b.get('tags', []))
                self.action_log.append(
                    f"[disappear]:[{_t}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{_le} disappears from ({bdx},{bdy}).|Object disappears from ({bdx},{bdy})."
                )
                self.action_log_l2.append(
                    f"[disappear]:[{_t}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{_l2}({bdx},{bdy})|Object({bdx},{bdy})"
                )


        for spr_id, spr in after_sprites.items():
            if not spr.is_visible:
                continue
            b = before_sprites.get(spr_id)
            if b is None or not b["visible"]:
                continue

            is_arm = ("arm" in b["tags"])
            pos_changed  = (spr.x, spr.y) != (b["x"], b["y"])
            size_changed = (spr.width, spr.height) != (b["width"], b["height"])


            if is_arm:
                a_arm_dir = self._get_arm_direction(spr)
                b_arm_dir = b["arm_dir"]



                rotation_count = self._arm_rotation_count_this_step.get(spr_id, 0)
                if b_arm_dir is not None and (a_arm_dir != b_arm_dir or rotation_count > 0):



                    if a_arm_dir == b_arm_dir and rotation_count > 0:
                        after_angle_display = b_arm_dir + rotation_count * 90
                    else:
                        after_angle_display = a_arm_dir
                    _rdx, _rdy, _rdw, _rdh = self._to_display_bbox(spr)
                    _t, _le, _l2 = self._display_for(spr)
                    self.action_log.append(
                        f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b_arm_dir})_({after_angle_display})]:"
                        f"{_le} at ({_rdx},{_rdy}) rotates from {b_arm_dir}° to {after_angle_display}°."
                        f"|Object at ({_rdx},{_rdy}) rotates from {b_arm_dir}° to {after_angle_display}°."
                    )
                    self.action_log_l2.append(
                        f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b_arm_dir})_({after_angle_display})]:"
                        f"({_rdx},{_rdy}){_l2}{b_arm_dir}°{after_angle_display}°"
                        f"|({_rdx},{_rdy})Object{b_arm_dir}°{after_angle_display}°"
                    )




                    if spr_id in self._arms_rotated_as_follower_this_step and pos_changed:
                        bdx, bdy = self._to_display_xy(b["x"], b["y"])
                        adx, ady, adw, adh = self._to_display_bbox(spr)

                        self.action_log.append(
                            f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:"
                            f"{_le} moves from ({bdx},{bdy}) to ({adx},{ady})."
                            f"|Object moves from ({bdx},{bdy}) to ({adx},{ady})."
                        )
                        self.action_log_l2.append(
                            f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:"
                            f"{_l2}({bdx},{bdy})({adx},{ady})"
                            f"|Object({bdx},{bdy})({adx},{ady})"
                        )
                    continue



                if size_changed:
                    b_len = max(b["width"],  b["height"])
                    a_len = max(spr.width,   spr.height)
                    if a_len != b_len:
                        verb = "extend" if a_len > b_len else "shrink"




                        gx, gy = spr.x, spr.y
                        gw, gh = spr.width, spr.height
                        if a_arm_dir == 0:

                            from_g = (gx,        gy + gh)
                            to_g   = (gx,        gy)
                            bbox_g = (+gw,  +gh)
                            if verb == "extend":
                                dir_en, dir_l2 = "upward",   ""
                            else:
                                dir_en, dir_l2 = "downward", ""
                        elif a_arm_dir == 90:

                            from_g = (gx,        gy)
                            to_g   = (gx + gw,   gy)
                            bbox_g = (-gw,  +gh)
                            if verb == "extend":
                                dir_en, dir_l2 = "rightward", ""
                            else:
                                dir_en, dir_l2 = "leftward",  ""
                        elif a_arm_dir == 180:

                            from_g = (gx,        gy)
                            to_g   = (gx,        gy + gh)
                            bbox_g = (+gw,  -gh)
                            if verb == "extend":
                                dir_en, dir_l2 = "downward", ""
                            else:
                                dir_en, dir_l2 = "upward",   ""
                        else:

                            from_g = (gx + gw,   gy)
                            to_g   = (gx,        gy)
                            bbox_g = (+gw,  +gh)
                            if verb == "extend":
                                dir_en, dir_l2 = "leftward",  ""
                            else:
                                dir_en, dir_l2 = "rightward", ""

                        f_dx, f_dy = self._to_display_xy(*from_g)
                        t_dx, t_dy = self._to_display_xy(*to_g)
                        _arc_scale = min(64 // self.camera.width, 64 // self.camera.height)
                        bb_dx = bbox_g[0] * _arc_scale
                        bb_dy = bbox_g[1] * _arc_scale
                        verb_l2 = "" if verb == "extend" else ""
                        _t, _le, _l2 = self._display_for(spr)
                        self.action_log.append(
                            f"[{verb}]:[{_t}]:[sname({spr.name});position({f_dx}_{f_dy})_({t_dx}_{t_dy});bbox({bb_dx}_{bb_dy})]:"
                            f"{_le} {verb}s {dir_en} from length {b_len} to {a_len}."
                            f"|Object {verb}s {dir_en} from length {b_len} to {a_len}."
                        )
                        self.action_log_l2.append(
                            f"[{verb}]:[{_t}]:[sname({spr.name});position({f_dx}_{f_dy})_({t_dx}_{t_dy});bbox({bb_dx}_{bb_dy})]:"
                            f"{_l2}{dir_l2}{b_len}{a_len}{verb_l2}"
                            f"|Object{dir_l2}{b_len}{a_len}{verb_l2}"
                        )
                        continue


                if pos_changed:
                    bdx, bdy = self._to_display_xy(b["x"], b["y"])
                    adx, ady, adw, adh = self._to_display_bbox(spr)
                    _t, _le, _l2 = self._display_for(spr)
                    self.action_log.append(
                        f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:"
                        f"{_le} moves from ({bdx},{bdy}) to ({adx},{ady})."
                        f"|Object moves from ({bdx},{bdy}) to ({adx},{ady})."
                    )
                    self.action_log_l2.append(
                        f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:"
                        f"{_l2}({bdx},{bdy})({adx},{ady})"
                        f"|Object({bdx},{bdy})({adx},{ady})"
                    )
                continue





            is_arm_follower = (
                spr_id in self._arms_following_resize_this_step
                or spr_id in self._arms_rotated_as_follower_this_step
            )
            if pos_changed and not is_arm_follower:
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                adx, ady, adw, adh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr)
                self.action_log.append(
                    f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:"
                    f"{_le} moves from ({bdx},{bdy}) to ({adx},{ady})."
                    f"|Object moves from ({bdx},{bdy}) to ({adx},{ady})."
                )
                self.action_log_l2.append(
                    f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:"
                    f"{_l2}({bdx},{bdy})({adx},{ady})"
                    f"|Object({bdx},{bdy})({adx},{ady})"
                )
            if spr.rotation != b["rotation"]:
                _rdx, _rdy, _rdw, _rdh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr)
                self.action_log.append(
                    f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:"
                    f"{_le} at ({_rdx},{_rdy}) rotates from {b['rotation']}° to {spr.rotation}°."
                    f"|Object at ({_rdx},{_rdy}) rotates from {b['rotation']}° to {spr.rotation}°."
                )
                self.action_log_l2.append(
                    f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:"
                    f"({_rdx},{_rdy}){_l2}{b['rotation']}°{spr.rotation}°"
                    f"|({_rdx},{_rdy})Object{b['rotation']}°{spr.rotation}°"
                )


        after_steps = self.step_counter.current_steps
        if after_steps != before_steps and self._bar_pixel_len(before_steps) != self._bar_pixel_len(after_steps):
            if after_steps < before_steps:
                self.action_log.append(
                    f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:"
                    f"The gray step bar at the bottom shrinks from the right ({before_steps}→{after_steps} steps remain)."
                    f"|The gray Object at the bottom shrinks from the right ({before_steps}→{after_steps})."
                )
                self.action_log_l2.append(
                    f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:"
                    f"{before_steps}→{after_steps}"
                    f"|Object{before_steps}→{after_steps}"
                )
            else:
                self.action_log.append(
                    f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:"
                    f"The gray step bar at the bottom extends to the right ({before_steps}→{after_steps} steps)."
                    f"|The gray Object at the bottom extends to the right ({before_steps}→{after_steps})."
                )
                self.action_log_l2.append(
                    f"[change]:[steps]:[sname(step_counter);count({before_steps})_({after_steps})]:"
                    f"{before_steps}→{after_steps}"
                    f"|Object{before_steps}→{after_steps}"
                )


        if hasattr(self, "_frame_sprite_log"):
            self._frame_sprite_log.append(self.get_sprite_status())
        if hasattr(self, "_frame_nonsprite_log"):
            self._frame_nonsprite_log.append(self.get_nonsprite_status())
        self._log_state.snapshot_step()

    def step(self) -> None:
        """













        """

        self.action_log    = []
        self.action_log_l2 = []

        self._arms_following_resize_this_step: set[int] = set()



        self._arms_rotated_as_follower_this_step: set[int] = set()



        self._arm_rotation_count_this_step: dict[int, int] = {}





        before_sprites = {
            id(spr): {
                "name":     spr.name,
                "x":        spr.x,
                "y":        spr.y,
                "width":    spr.width,
                "height":   spr.height,
                "rotation": spr.rotation,
                "visible":  spr.is_visible,
                "tags":     tuple(spr._tags) if spr._tags else (),
                "arm_dir":  self._get_arm_direction(spr) if (spr._tags and "arm" in spr._tags) else None,
            }
            for spr in self.current_level.get_sprites()
        }
        before_steps = self.step_counter.current_steps







        if self.saved_state:
            for sprite in self.saved_state:
                if sprite._tags and "arm" in sprite._tags:
                    self._mark_follower_descendants(sprite)
            for sprite, saved in self.saved_state.items():
                sprite.set_position(saved.x, saved.y)
                sprite.pixels = saved.pixels
            self.saved_state = dict()

        elif self.action.id == GameAction.ACTION6:

            self.step_counter.decrement()
            click_x = self.action.data.get("x", 0)
            click_y = self.action.data.get("y", 0)
            grid_pos = self.camera.display_to_grid(click_x, click_y)

            collision_pending = False

            if grid_pos:
                game_x, game_y = grid_pos


                pivot_hit = self.current_level.get_sprite_at(game_x, game_y, "pivot")
                if pivot_hit:
                    pivot_color = pivot_hit.pixels[pivot_hit.height // 2, pivot_hit.height // 2]
                    arm_sprites = self.current_level.get_sprites_by_tag("arm")
                    self.saved_state = dict()
                    for arm in arm_sprites:
                        arm_color = arm.pixels[1, 1]
                        if arm_color == pivot_color:
                            self._save_state(arm)

                            parents = [k for k, v in self.arm_children.items() if arm in v]
                            if parents:
                                parent = parents[0]
                                parent_dir = self._get_arm_direction(parent)
                                arm_dir    = self._get_arm_direction(arm)
                                if abs(arm_dir - 90 - parent_dir) == 180:
                                    self._rotate_arm_90(arm)
                                self._rotate_arm_90(arm)
                            else:
                                self._rotate_arm_90(arm)
                    if self._check_arm_overlap():


                        collision_pending = True
                    else:
                        self.saved_state = dict()

                else:

                    socket_hit = self.current_level.get_sprite_at(game_x, game_y, "double_socket")
                    if socket_hit:
                        is_horizontal = socket_hit.width > socket_hit.height
                        half_size = socket_hit.width // 2 if is_horizontal else socket_hit.height // 2
                        click_offset = game_x - socket_hit.x if is_horizontal else game_y - socket_hit.y
                        self.saved_state = dict()
                        for arm in self.socket_arms[socket_hit]:
                            self._save_state(arm)

                            if arm.height > arm.width:
                                seg_count = arm.height // ARM_WIDTH
                            else:
                                seg_count = arm.width // ARM_WIDTH
                            if click_offset > half_size:
                                self._resize_arm(arm, seg_count + 1)
                            elif click_offset < half_size and seg_count > 1:
                                self._resize_arm(arm, seg_count - 1)
                        if self._check_arm_overlap():

                            collision_pending = True
                        else:
                            self.saved_state = dict()




            if collision_pending:
                self._post_step(before_sprites, before_steps)
                return









        win_triggered = False
        loss_triggered = False
        if self._check_win():
            win_triggered = True
            self.next_level()
        elif not self.step_counter.current_steps:
            loss_triggered = True
            self.lose()
        self.complete_action()

        if win_triggered:
            self._set_event("win", {
                "en": "[win]:[game]:[]:The level is cleared.|The level is cleared.",
                "l2": "[win]:[game]:[]:|",
            })
        if loss_triggered:
            self._set_event("gameover", {
                "en": "[gameover]:[game]:[]:Step counter reached zero, game over.|Game over.",
                "l2": "[gameover]:[game]:[]:0|",
            })


        self._post_step(before_sprites, before_steps)





    def _set_event(self, key: str, value) -> None:
        """
        """
        self._log_state.set_event(key, value)


    @property
    def action_log(self) -> list[str]:
        return self._log_state._step_log
    @action_log.setter
    def action_log(self, value: list[str]) -> None:
        self._log_state._step_log = value

    @property
    def action_log_l2(self) -> list[str]:
        return self._log_state._step_log_l2
    @action_log_l2.setter
    def action_log_l2(self, value: list[str]) -> None:
        self._log_state._step_log_l2 = value

    @property
    def _frame_action_logs(self) -> list[list[str]]:
        return self._log_state._frames
    @_frame_action_logs.setter
    def _frame_action_logs(self, value: list[list[str]]) -> None:
        self._log_state._frames = value

    @property
    def _frame_action_logs_l2(self) -> list[list[str]]:
        return self._log_state._frames_l2
    @_frame_action_logs_l2.setter
    def _frame_action_logs_l2(self, value: list[list[str]]) -> None:
        self._log_state._frames_l2 = value

    def reset_logs(self) -> None:
        self._log_state.reset()

    def get_action_log_frame(self) -> tuple[list[list[str]], list[list[str]]]:
        return self._log_state.get_frame_logs()

    def get_action_log(self) -> tuple[list[str], list[str]]:
        return self._log_state.get_action_log()

    def get_sprite_status(self) -> list[dict]:
        """




        """
        result = []
        for spr in self.current_level.get_sprites():
            if not spr.is_visible:
                continue
            tags     = list(spr._tags) if spr._tags else []



            _arm_t, _arm_le, _arm_l2 = self._arm_role(spr)
            if _arm_le is not None:
                label    = _arm_le
                label_l2 = _arm_l2
            else:
                label    = next(
                    (TAG_DISPLAY_NAMES[t] for t in tags if t in TAG_DISPLAY_NAMES),
                    spr.name,
                )
                label_l2 = next(
                    (TAG_DISPLAY_NAMES_L2[t] for t in tags if t in TAG_DISPLAY_NAMES_L2),
                    spr.name,
                )
            result.append({
                "spr_id":   id(spr),
                "name":     spr.name,
                "label":    label,
                "label_l2": label_l2,
                "tags":     tags,
                "x":        spr.x,
                "y":        spr.y,
                "width":    spr.width,
                "height":   spr.height,
                "rotation": spr.rotation,
            })
        return result

    def get_nonsprite_status(self) -> list[dict]:
        """




        """
        return [
            {
                "name":     "step_counter",
                "label":    "Steps remaining",
                "label_l2": ''                     ,
                "value":    self.step_counter.current_steps,
                "max":      self.step_counter.max_steps,
                "x":        0,
                "y":        63,
                "width":    64,
                "height":   1,
            }
        ]

    def get_game_knowledge(self) -> dict:
        """



        """
        return GAME_KNOWLEDGE
